<?php
require_once __DIR__.'/../config/session.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/helper.php';require_once __DIR__.'/../config/auth.php';check_access([2]);
$db=Database::getInstance();$stmt=$db->prepare('SELECT id,nama_lengkap FROM guru WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$guru=$stmt->fetch();if(!$guru){http_response_code(403);exit('Data guru tidak ditemukan.');}$guru_id=(int)$guru['id'];
$success=$_SESSION['kak_success']??'';$error=$_SESSION['kak_error']??'';unset($_SESSION['kak_success'],$_SESSION['kak_error']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if(!verify_csrf($_POST['csrf_token']??'')){$_SESSION['kak_error']='Sesi keamanan berakhir. Silakan muat ulang halaman.';redirect('kak.php');}
 try{
  if($action==='simpan_target'){
   $target=$_POST['target']??[];foreach(['X','XI','XII'] as $tingkat){if(!isset($target[$tingkat])||filter_var($target[$tingkat],FILTER_VALIDATE_INT,['options'=>['min_range'=>0,'max_range'=>100000]])===false)throw new InvalidArgumentException('Target poin harus berupa angka 0 sampai 100.000.');}
   $db->beginTransaction();$upsert=$db->prepare('INSERT INTO kak_target_tingkat(tingkat,target_poin,diubah_oleh) VALUES(?,?,?) ON DUPLICATE KEY UPDATE target_poin=VALUES(target_poin),diubah_oleh=VALUES(diubah_oleh)');foreach(['X','XI','XII'] as $tingkat)$upsert->execute([$tingkat,(int)$target[$tingkat],$guru_id]);$db->commit();catat_log($_SESSION['user_id'],'Memperbarui target poin KAK tingkat X, XI, dan XII');$_SESSION['kak_success']='Target poin KAK berhasil disimpan.';
  }elseif($action==='tambah_aktivitas'){
   $siswa_id=filter_var($_POST['siswa_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$poin=filter_var($_POST['poin']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>100000]]);$nama=trim($_POST['nama_aktivitas']??'');$ket=trim($_POST['keterangan']??'');$tanggal=trim($_POST['tanggal_aktivitas']??'');$tgl=DateTime::createFromFormat('!Y-m-d',$tanggal);
   if(!$siswa_id||!$poin||$nama===''||mb_strlen($nama)>150||mb_strlen($ket)>500||!$tgl||$tgl->format('Y-m-d')!==$tanggal)throw new InvalidArgumentException('Data aktivitas tidak lengkap atau tidak valid.');
   $cek=$db->prepare('SELECT nama_lengkap FROM siswa WHERE id=?');$cek->execute([$siswa_id]);$nama_siswa=$cek->fetchColumn();if(!$nama_siswa)throw new InvalidArgumentException('Siswa tidak ditemukan.');$ins=$db->prepare('INSERT INTO kak_aktivitas_siswa(siswa_id,guru_id,nama_aktivitas,keterangan,tanggal_aktivitas,poin) VALUES(?,?,?,?,?,?)');$ins->execute([$siswa_id,$guru_id,$nama,$ket?:null,$tanggal,$poin]);catat_log($_SESSION['user_id'],"Memberikan $poin poin KAK kepada $nama_siswa untuk aktivitas $nama");$_SESSION['kak_success']='Aktivitas dan poin siswa berhasil ditambahkan.';
  }elseif($action==='hapus_aktivitas'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)throw new InvalidArgumentException('Aktivitas tidak valid.');$del=$db->prepare('DELETE FROM kak_aktivitas_siswa WHERE id=? AND guru_id=?');$del->execute([$id,$guru_id]);if($del->rowCount()!==1)throw new InvalidArgumentException('Aktivitas tidak ditemukan atau dicatat oleh guru lain.');catat_log($_SESSION['user_id'],"Menghapus catatan aktivitas KAK #$id");$_SESSION['kak_success']='Catatan aktivitas berhasil dihapus.';
  }else throw new InvalidArgumentException('Aksi tidak dikenali.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Proses KAK gagal: '.$e->getMessage());$_SESSION['kak_error']=$e instanceof InvalidArgumentException?$e->getMessage():'Data KAK gagal disimpan.';}redirect('kak.php');
}
$targets=['X'=>0,'XI'=>0,'XII'=>0];foreach($db->query('SELECT tingkat,target_poin FROM kak_target_tingkat')->fetchAll() as $row)$targets[$row['tingkat']]=(int)$row['target_poin'];
$siswa_list=$db->query('SELECT s.id,s.nama_lengkap,s.nis,k.nama_kelas,k.tingkat,COALESCE(SUM(a.poin),0) total_poin FROM siswa s LEFT JOIN kelas k ON k.id=s.kelas_id LEFT JOIN kak_aktivitas_siswa a ON a.siswa_id=s.id GROUP BY s.id,s.nama_lengkap,s.nis,k.nama_kelas,k.tingkat ORDER BY k.tingkat,k.nama_kelas,s.nama_lengkap')->fetchAll();
$riwayat=$db->query('SELECT a.*,s.nama_lengkap nama_siswa,k.nama_kelas,g.nama_lengkap nama_guru FROM kak_aktivitas_siswa a JOIN siswa s ON s.id=a.siswa_id LEFT JOIN kelas k ON k.id=s.kelas_id JOIN guru g ON g.id=a.guru_id ORDER BY a.created_at DESC,a.id DESC LIMIT 100')->fetchAll();
?>
