<?php if($success):?><div class="alert alert-success alert-dismissible fade show"><?=sanitize($success)?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif;?><?php if($error):?><div class="alert alert-danger alert-dismissible fade show"><?=sanitize($error)?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif;?>
<div class="row g-3 mb-3"><div class="col-lg-5"><section class="card kak-card h-100"><div class="card-body p-4"><h2 class="h6 fw-bold mb-3">Target Minimum per Tingkat</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=sanitize($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="simpan_target"><div class="row target-grid g-2"><?php foreach(['X','XI','XII'] as $tingkat):?><div class="col"><label class="form-label small fw-semibold">Tingkat <?=$tingkat?></label><div class="input-group"><input type="number" name="target[<?=$tingkat?>]" min="0" max="100000" class="form-control" value="<?=$targets[$tingkat]?>" required><span class="input-group-text">poin</span></div></div><?php endforeach;?></div><button class="btn btn-primary w-100 mt-3"><i class="fa-solid fa-floppy-disk me-1"></i>Simpan Target</button></form></div></section></div>
<div class="col-lg-7"><section class="card kak-card h-100"><div class="card-body p-4"><h2 class="h6 fw-bold mb-3">Berikan Poin Aktivitas</h2><form method="post" id="formPoin"><input type="hidden" name="csrf_token" value="<?=sanitize($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="tambah_aktivitas"><div class="mb-2"><label class="form-label fw-semibold">Siswa</label><select name="siswa_id" class="form-select" required><option value="">-- Pilih siswa --</option><?php foreach($siswa_list as $s):?><option value="<?=(int)$s['id']?>"><?=sanitize($s['nama_lengkap'].' · '.($s['nama_kelas']?:'Tanpa kelas').' · '.$s['total_poin'].' poin')?></option><?php endforeach;?></select></div><div class="row g-2"><div class="col-md-8"><label class="form-label fw-semibold">Nama aktivitas</label><input name="nama_aktivitas" maxlength="150" class="form-control" placeholder="Contoh: Lomba kebersihan antarkelas" required></div><div class="col-md-4"><label class="form-label fw-semibold">Poin</label><input type="number" name="poin" min="1" max="100000" class="form-control" required></div><div class="col-md-5"><label class="form-label fw-semibold">Tanggal aktivitas</label><input type="date" name="tanggal_aktivitas" class="form-control" value="<?=date('Y-m-d')?>" required></div><div class="col-md-7"><label class="form-label fw-semibold">Keterangan <small class="text-muted">(opsional)</small></label><input name="keterangan" maxlength="500" class="form-control"></div></div><button class="btn btn-success w-100 mt-3"><i class="fa-solid fa-plus me-1"></i>Tambahkan Aktivitas dan Poin</button></form></div></section></div></div>
<section class="card kak-card"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h6 fw-bold mb-0">Riwayat Pemberian Poin</h2><span class="badge bg-primary-subtle text-primary">100 catatan terbaru</span></div><div class="table-responsive"><table class="table table-hover history-table"><thead><tr><th>Tanggal</th><th>Siswa</th><th>Aktivitas</th><th>Poin</th><th>Diberikan oleh</th><th></th></tr></thead><tbody><?php if(!$riwayat):?><tr><td colspan="6" class="text-center text-muted py-4">Belum ada riwayat aktivitas.</td></tr><?php else:foreach($riwayat as $r):?><tr><td class="text-nowrap"><?=date('d M Y',strtotime($r['tanggal_aktivitas']))?></td><td><strong><?=sanitize($r['nama_siswa'])?></strong><small class="d-block text-muted"><?=sanitize($r['nama_kelas']?:'Tanpa kelas')?></small></td><td><?=sanitize($r['nama_aktivitas'])?><?php if($r['keterangan']):?><small class="d-block text-muted"><?=sanitize($r['keterangan'])?></small><?php endif;?></td><td><span class="badge bg-success-subtle text-success">+<?=(int)$r['poin']?></span></td><td><?=sanitize($r['nama_guru'])?></td><td><?php if((int)$r['guru_id']===$guru_id):?><form method="post" onsubmit="return confirm('Hapus poin aktivitas ini? Total poin siswa akan ikut berkurang.')"><input type="hidden" name="csrf_token" value="<?=sanitize($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="hapus_aktivitas"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-danger" aria-label="Hapus aktivitas"><i class="fa-solid fa-trash"></i></button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div></section>
</main></div><script>document.getElementById('formPoin')?.addEventListener('submit',function(e){if(!confirm('Tambahkan aktivitas dan poin ini kepada siswa terpilih?'))e.preventDefault();});</script><?php require_once __DIR__.'/../includes/footer.php';?>
